const GOLD=[[138,95,22],[255,236,160],[222,168,48],[255,248,214],[170,120,30]],PLAT=[[58,68,82],[232,240,250],[128,141,158],[250,252,255],[74,86,102]],OFF=[0,.28,.5,.72,1];
